228	    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
229	    public boolean isPaid() {
230	        return status == ReservationStatus.CONFIRMED
231	                || status == ReservationStatus.CHECKED_IN
232	                || status == ReservationStatus.CHECKED_OUT;
233	    }
234	
235	    /** The money the inn keeps from this reservation. */
236	    public BigDecimal amountKept() {
237	        return refund == null ? amountPaid : amountPaid.subtract(refund);
238	    }
239	
240	    void changeStatus(ReservationStatus newStatus) {
241	        this.status = newStatus;
242	    }
243	
244	    void confirmPayment() {
245	        this.status = ReservationStatus.CONFIRMED;
246	        this.amountPaid = price.total();
247	    }
