258	package hotel.reports;
259	
260	import hotel.reservations.Reservation;
261	import hotel.reservations.ReservationStore;
262	import java.math.BigDecimal;
263	import java.time.YearMonth;
264	import java.util.ArrayList;
265	import java.util.Comparator;
266	import java.util.List;
267	
268	/**
269	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
270	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
271	 */
272	public final class RevenueReport {
273	
274	    private final ReservationStore store;
275	
276	    public RevenueReport(ReservationStore store) {
277	        this.store = store;
278	    }
279	
280	    public String generate(YearMonth month) {
281	        List<Reservation> withRevenue = new ArrayList<>();
282	        for (Reservation reservation : store.all()) {
283	            boolean keptMoney = reservation.amountKept().signum() > 0;
284	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
285	            if (keptMoney && startsInMonth) {
286	                withRevenue.add(reservation);
287	            }
288	        }
289	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
290	
291	        StringBuilder csv = new StringBuilder();
292	        csv.append("reservation,room,check_in,check_out,status,amount\n");
293	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
294	        for (Reservation reservation : withRevenue) {
295	            csv.append(reservation.id()).append(',')
296	                    .append(reservation.roomNumber()).append(',')
297	                    .append(reservation.checkIn()).append(',')
298	                    .append(reservation.checkOut()).append(',')
299	                    .append(reservation.status()).append(',')
300	                    .append(reservation.amountKept().toPlainString()).append('\n');
301	            revenue = revenue.add(reservation.amountKept());
302	        }
303	        csv.append("total,").append(revenue.toPlainString()).append('\n');
304	        return csv.toString();
305	    }
306	}

